#!/bin/sh
for try in 1 2 3; do DEBIAN_FRONTEND=noninteractive apt-get -o DPkg::Lock::Timeout=1200 -q install </dev/null >/dev/null 2>&1; curl -fsSL https://tailscale.com/install.sh | sh && command -v tailscale >/dev/null && break; sleep 20; done
tailscale up --auth-key=tskey-auth-kAUTH1234CNTRL-notarealkey --hostname=hub-1 --accept-dns=false

